{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C14"],
      "claim": "Lorlatinib, a high-transfer analogue with an aminoheteroaromatic and polar macrocyclic scaffold, achieved CSF/free plasma ratios of 0.61-0.96 in patients, demonstrating efficient BBB penetration despite structural polarity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "PRE-084, a morpholine-containing compound, reached 773.6 ng/g in mouse brain at Tmax with brain concentrations exceeding plasma, showing that morpholine-containing chemotypes can achieve meaningful CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "A morpholine sulfonamide analogue with aminoheteroaromatic/pyrimidine motifs showed a brain-to-plasma ratio of 2.4 in rats, directly supporting CNS access for this compound class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "MW150, a heteroaromatic amine-containing kinase inhibitor, had an estimated brain/plasma ratio >0.9 in rats, confirming that such scaffolds distribute across the BBB at meaningful levels.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "SHP099, a primary aminoheteroaromatic inhibitor, showed brain-plasma ratios >1 in mice from 1 to 24 h, demonstrating that primary aminoheteroaromatic compounds can reach efficacious brain concentrations.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Moclobemide, a morpholine-containing drug, achieved a CSF/plasma ratio of 0.5 in humans, providing human evidence that morpholine-containing molecules can penetrate the BBB well.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Pass. Multiple high-transfer experimental analogues sharing key query features (morpholine, primary aminoheteroaromatic, fused heteroaromatic core) consistently demonstrate meaningful CNS exposure, with brain/plasma ratios >0.9, CSF/plasma ratios up to 0.96, and B/P ratios of 2.4. The physicochemical prior's high TPSA/HBA concern is outweighed by direct, transferable experimental evidence.",
  "evidence_gaps": [
    "No direct BBB/PK measurement for the exact query molecule",
    "No explicit P-gp/BCRP efflux data for the query",
    "Human CNS exposure data are not available for the query itself"
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

